function v18MonsterDisplayName(a){const u=a?.drop?MONSTERS[a.drop]:null;if(u?.name)return u.name;return a?.enemy||'不明'}function v18EnhanceAdventCards(){const cards=[...document.querySelectorAll('.v7-advent')],aids=Object.keys(V7_ADVENT_BASE);cards.forEach((card,i)=>{if(card.querySelector('.v18-monster-name'))return;const a=V7_ADVENT_BASE[aids[i]];if(!a)return;const info=card.querySelector('.unit-row > div:last-child');if(info){const line=document.createElement('div');line.className='v18-monster-name';line.innerHTML=`<span>MONSTER</span><b>${v18MonsterDisplayName(a)}</b>`;const meta=info.querySelector('.tiny.muted');if(meta)info.insertBefore(line,meta);else info.appendChild(line)}})}const V18_QUEST=questView;questView=function(m){V18_QUEST(m);v18EnhanceAdventCards()};const V18_HEADER=header;header=function(){return V18_HEADER().replace('TYPE SCRIPT v17','TYPE SCRIPT v18')};S.version=18;save();render();
